from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class NrduParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        bts_id = self.enb_ent_config['id']
        self.set_parameter('maxNumOfRrcConUEsPerDU', '26928')
        self.set_parameter('numOfDrbsReservForEmergency', '0')
        self.set_parameter('targetDN', f'MRBTS-{bts_id}/EQM-1/APEQM-1')
        cells = []
        for cell in self.enb_ent_config['cells']:
            cells.append(cell)
        self.set_struct_parameter('refNrCellGroup', cells)
        if self.is_ecpri_72a(self.mo_num):
            self.set_parameter('flexibleCAMode', 'NumberCellAmount')
        else:
            self.set_parameter('flexibleCAMode', 'BasicCAMode')
